// embed.js -- the t27 player: one spec, compiled in the reader's browser, inside a post.
//
// Built from the t27 spec beside it. `player.t27` (generated byte for byte from
// apps/website/specs/x/player.t27 by scripts/play-from-spec.mjs) is fetched and compiled here
// with the same t27_compiler.wasm as the spec it plays, and the tabs, the length of the compile
// piece, the autoplay keys, the debounce and the tests note are its constants. A value missing
// from it stops the player with the compiler's reason; nothing falls back to a copy kept here.
//
// Every number on screen is the compiler's answer for the file being shown, read when it is
// shown: tokens, nodes, depth, the type check, HIR, the bytes each backend emitted and the
// spec's own test blocks (run by ./t27run.js, which never counts a skip as a pass).
//
// The colours are the spec explorer's: ./site.js is generated from the site's own highlighter and
// palette (SITE_MODULES in player.t27), so a spec reads the same here as on t27.ai. The RTL tab
// reads the emitted Verilog with ./rtl.js; the Term tab is a terminal over the same compiler,
// ./shell.js.
//
// Query: spec=<path under t27/files/>  cast=<recording id under term/>  v=<player build>
//        autoplay=1 | auto_play=true (X adds both on click)  tab=<one of the spec's TABS>
//        backend=<one of the spec's BACKENDS, the terminal's first>


const $ = (sel) => document.querySelector(sel)
const root = new URL('../', import.meta.url)
const query = new URLSearchParams(location.search)
const build = (query.get('v') || '').replace(/[^A-Za-z0-9]/g, '').slice(0, 32)
const at = (path) => new URL(path + (build ? `?v=${build}` : ''), root)
const SPEC_PATH_RE = /^specs\/[A-Za-z0-9_\-/.]+\.t27$/
const CAST_ID_RE = /^[a-z0-9][a-z0-9-]{0,63}$/
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches
const html = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const fmt = (n) => Number(n).toLocaleString('en-US')
const status = (text, cls = '') => { $('#status').innerHTML = cls ? `<span class="${cls}">${text}</span>` : text }
// The site's highlighter and palette, and the Verilog reader, loaded in main() so a failure
// reaches the status line.
let site = null
let readRtl = null
let shell = null
// player.t27's constants, once read.
let cfg = null

// --- the compiler ---------------------------------------------------------------------------
async function loadCompiler() {
  const res = await fetch(at('t27/t27_compiler.wasm'))
  if (!res.ok) throw new Error(`the compiler did not load (HTTP ${res.status})`)
  const { instance } = await WebAssembly.instantiate(await res.arrayBuffer(), {})
  const w = instance.exports
  const enc = new TextEncoder()
  // t27_analyze takes ownership of the input; the answer is [u32 LE length][utf-8 JSON].
  return function analyze(source, name) {
    const bytes = enc.encode(source)
    const inPtr = w.t27_alloc(bytes.length)
    new Uint8Array(w.memory.buffer, inPtr, bytes.length).set(bytes)
    let out
    if (name && w.t27_analyze_named) {
      const nb = enc.encode(name)
      const namePtr = w.t27_alloc(nb.length)
      new Uint8Array(w.memory.buffer, namePtr, nb.length).set(nb)
      out = w.t27_analyze_named(inPtr, bytes.length, namePtr, nb.length)
    } else out = w.t27_analyze(inPtr, bytes.length)
    const len = new DataView(w.memory.buffer).getUint32(out, true)
    const json = new TextDecoder().decode(new Uint8Array(w.memory.buffer, out + 4, len))
    w.t27_free(out, 4 + len)
    return JSON.parse(json)
  }
}

// The player's own spec. play-from-spec.mjs has already refused any constant that is not a
// string, a bool, an unsigned integer or an array of strings, so those are the shapes read here;
// anything else is an error, not a guess.
function playerConfig(analysis) {
  if (!analysis.typecheck?.ok || analysis.hir?.ok === false) throw new Error(`player.t27 does not compile: ${analysis.astError || analysis.hir?.error || (analysis.typecheck?.errors ?? []).join('; ')}`)
  const lit = (e, name) => {
    if (e.kind === 'ExprArrayLiteral') return (e.children ?? []).map((c) => lit(c, name))
    if (e.kind !== 'ExprLiteral') throw new Error(`player.t27: ${name} is a ${e.kind}, not a literal`)
    if (e.nodeKind === 'string') return e.value ?? ''
    if (e.value === 'true' || e.value === 'false') return e.value === 'true'
    if (/^\d+$/.test(e.value ?? '')) return Number(e.value)
    throw new Error(`player.t27: ${name} = ${e.value} is not a value this player reads`)
  }
  const cfg = {}
  for (const d of analysis.ast?.children ?? []) if (d.kind === 'ConstDecl' && d.children?.[0]) cfg[d.name] = lit(d.children[0], d.name)
  const need = ['TABS', 'TAB_LABELS', 'FIRST_TAB', 'WIDE_MIN_PX', 'COMPILE_ANIMATION_MS', 'AUTOPLAY_LIMIT_MS', 'AUTOPLAY_PARAMS', 'RECOMPILE_DEBOUNCE_MS', 'EDITOR_TOUCH_FONT_PX', 'TESTS_NOTE', 'ORIGIN', 'SPEC_PAGE', 'PLAY_SPECS', 'PLAY_CASTS', 'PLAY_IDS', 'HAS_SOUND',
    'STAGES', 'BACKENDS', 'BACKEND_NAMES', 'BACKEND_EXTS', 'BACKEND_PAGES', 'BACKEND_RUN_LOCAL', 'RUNS_IN_BROWSER', 'SHELL_COMMANDS', 'SHELL_ARGS', 'SHELL_HELP', 'SHELL_CHIPS', 'SHELL_NOTE', 'SHELL_DEMO', 'SHELL_TYPE_MS']
  const missing = need.filter((k) => !(k in cfg))
  if (missing.length) throw new Error(`player.t27 lacks ${missing.join(', ')}`)
  if (cfg.COMPILE_ANIMATION_MS > cfg.AUTOPLAY_LIMIT_MS) throw new Error('player.t27: the compile piece is longer than the autoplay limit')
  if (cfg.STAGES?.length !== 7) throw new Error('player.t27: STAGES must name the seven compile stages')
  return cfg
}

// --- highlighting, with the spec explorer's highlighter ----------------------------------------
const spansHtml = (spans) => spans.map((sp) => (sp.cls === 'plain' ? html(sp.text) : `<span class="h-${sp.cls}">${html(sp.text)}</span>`)).join('')

// The compiler's own tokens, coloured, one string per line; a line the compiler dropped or
// rejected is marked.
function highlight(rows, analysis) {
  const hit = new Set()
  for (const list of [analysis.discarded, analysis.lexerDiscarded, analysis.swallowed]) for (const e of list ?? []) if (e && e.line) hit.add(e.line)
  for (const e of analysis.typecheck?.errors ?? []) { const m = /line (\d+)/.exec(e); if (m) hit.add(Number(m[1])) }
  return rows.map((spans, i) => `<span class="l${hit.has(i + 1) ? ' hit' : ''}">${spansHtml(spans) || ' '}</span>`)
}

// Between compiles: the lines the last compile saw keep its colours, and the lines typed since
// are drawn plain. The textarea's own text is transparent, so this is the only place a keystroke
// shows; waiting for the compile left a phone typist looking at nothing for about two seconds.
function repaint(lines, painted) {
  const old = painted.lines
  let head = 0
  while (head < lines.length && head < old.length && lines[head] === old[head]) head++
  let tail = 0
  while (tail < lines.length - head && tail < old.length - head && lines[lines.length - 1 - tail] === old[old.length - 1 - tail]) tail++
  return lines.map((text, i) => {
    if (i < head) return painted.html[i]
    if (i >= lines.length - tail) return painted.html[i - lines.length + old.length]
    return `<span class="l">${html(text) || ' '}</span>`
  })
}

// Tokens per highlight class, for the lexer bar: every token is its own span.
const TOKEN_CLASSES = ['kw', 'type', 'ident', 'num', 'str', 'op', 'punct']
function classCounts(rows) {
  const out = {}
  for (const spans of rows) for (const sp of spans) if (TOKEN_CLASSES.includes(sp.cls)) out[sp.cls] = (out[sp.cls] || 0) + 1
  return out
}

function codeHtml(code, backend) {
  return spansHtml(site.highlightCode(code, site.TARGET_LANG[backend] ?? backend).flatMap((spans, i) => (i ? [{ text: '\n', cls: 'plain' }, ...spans] : spans)))
}

// Copy and download, for every block of emitted text. The clipboard API is refused inside some
// frames; the textarea route is the fallback, and the button says which way it went.
function copyText(text, btn) {
  const said = btn.textContent
  const done = (ok) => { btn.textContent = ok ? 'copied' : 'copy blocked'; setTimeout(() => { btn.textContent = said }, 1400) }
  const legacy = () => {
    const ta = Object.assign(document.createElement('textarea'), { value: text })
    ta.style.cssText = 'position:fixed;opacity:0;top:0;left:0'
    document.body.appendChild(ta)
    ta.select()
    let ok = false
    try { ok = document.execCommand('copy') } catch { ok = false }
    ta.remove()
    return ok
  }
  if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(() => done(true), () => done(legacy()))
  else done(legacy())
}
function download(text, name) {
  const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(new Blob([text], { type: 'text/plain' })), download: name })
  document.body.appendChild(a)
  a.click()
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove() }, 0)
}
// The file a backend's output is saved as, and the facts every tab shows: ./shell.js, which the
// generator's test runs without a page.
const fileName = (backend, code, stem) => shell.fileName(cfg, backend, code, stem)
const factsOf = (source, analysis) => shell.factsOf(cfg, source, analysis)

// --- compile: the run as one short linear piece ---------------------------------------------
function icicle(ast) {
  const leaves = new Map()
  const count = (n) => { const k = n.children ?? []; const v = k.length ? k.reduce((s, c) => s + count(c), 0) : 1; leaves.set(n, v); return v }
  const total = count(ast)
  const rows = []
  const walk = (n, x, d) => {
    ;(rows[d] ??= []).push({ n, x, w: leaves.get(n) / total })
    let cx = x
    for (const c of n.children ?? []) { walk(c, cx, d + 1); cx += leaves.get(c) / total }
  }
  walk(ast, 0, 0)
  const K = site.CLS_COLOR
  const colour = (k) => (/Test|Invariant|Bench/.test(k) ? K.kw : /Decl|Module|Use/.test(k) ? K.ident : k.startsWith('Stmt') ? K.op : k.startsWith('Expr') ? K.num : K.punct)
  const H = 100 / rows.length
  const svg = rows.map((row, d) => `<g data-d="${d}">${row.map((r) => `<rect x="${(r.x * 1000).toFixed(2)}" y="${(d * H).toFixed(3)}" width="${Math.max(0.6, r.w * 1000 - 0.6).toFixed(2)}" height="${(H * 0.86).toFixed(3)}" fill="${colour(r.n.kind)}"><title>${html(r.n.kind)}${r.n.name ? ' ' + html(r.n.name) : ''}</title></rect>`).join('')}</g>`).join('')
  return { svg: `<svg viewBox="0 0 1000 100" preserveAspectRatio="none" role="img" aria-label="The syntax tree, ${rows.length} levels deep">${svg}</svg>`, depth: rows.length }
}

function renderCompile(pane, f, analysis, classes) {
  const totalBackendBytes = f.backends.reduce((s, b) => s + (b.ok ? b.bytes : 0), 0)
  const okBackends = f.backends.filter((b) => b.ok).length
  const t = f.tests
  const testLine = t.error ? `<span class="r">${html(t.error)}</span>` : `<span class="g">${t.pass} pass</span> <i>&middot;</i> <span class="${t.fail ? 'r' : ''}">${t.fail} fail</span> <i>&middot;</i> <span class="y">${t.skip} skip</span>`
  const counted = Object.values(classes).reduce((s, n) => s + n, 0)
  const tokbar = Object.entries(classes).sort((a, b) => b[1] - a[1]).map(([c, n]) => `<i style="width:${((n / Math.max(1, counted)) * 100).toFixed(2)}%;background:${site.CLS_COLOR[c]}" title="${c}: ${n}"></i>`).join('')
  // The stage names are STAGES in player.t27; `t27c check` in the terminal prints the same ones.
  const stages = [
    `${fmt(f.bytes)} <i>bytes &middot;</i> ${fmt(f.lines)} <i>lines</i>`,
    `${fmt(f.tokens)} <i>tokens &middot;</i> ${f.kinds} <i>kinds</i>${f.discarded ? ` <span class="r">&middot; ${f.discarded} dropped</span>` : ''}<div class="tokbar">${tokbar}</div>`,
    f.astError ? `<span class="r">${html(f.astError)}</span>` : `${fmt(f.nodes)} <i>nodes &middot; depth</i> ${f.depth} <i>&middot;</i> <span class="nw">${f.topLevel} <i>top-level</i></span>`,
    f.typeOk ? `<span class="g">ok</span> <i>&middot; 0 errors</i>` : `<span class="r">${f.typeErrors.length} error(s)</span> <i>${html(f.typeErrors[0] ?? '')}</i>`,
    f.hirOk ? `<span class="g">ok</span> <i>&middot;</i> ${fmt(f.hirBytes)} <i>bytes</i>` : `<span class="r">failed</span>`,
    `<span class="${okBackends === f.backends.length ? 'g' : 'y'}">${okBackends}/${f.backends.length}</span> <i>&middot;</i> ${fmt(totalBackendBytes)} <i>bytes emitted</i>`,
    testLine,
  ].map((v, i) => [cfg.STAGES[i], v])
  const tree = analysis.ast ? icicle(analysis.ast) : { svg: '<svg></svg>', depth: 0 }
  const maxBytes = Math.max(1, ...f.backends.map((b) => b.bytes))
  pane.innerHTML = `<div class="cmp">
<ol class="stages">${stages.map(([lb, vl]) => `<li><span class="lb">${lb}</span><span class="vl">${vl}</span></li>`).join('')}</ol>
<div class="viz"><h4><span>syntax tree</span><span>${fmt(f.nodes)} nodes</span></h4>${tree.svg}
<h4><span>backends</span><span class="ctl"><button type="button" data-k="play" aria-label="Play" title="Play">&#9654;</button><button type="button" data-k="again" aria-label="Replay" title="Replay">&#8635;</button></span></h4>
<div class="bars">${f.backends.map((b) => `<span>${b.name}</span><div><i class="${b.ok ? '' : 'x'}" data-w="${b.ok ? ((b.bytes / maxBytes) * 100).toFixed(1) : 100}"></i></div><em>${b.ok ? fmt(b.bytes) : 'failed'}</em>`).join('')}</div></div>
</div>`
  return tree.depth
}

function piece(pane, depth, ms) {
  const li = [...pane.querySelectorAll('.stages li')]
  const groups = [...pane.querySelectorAll('.viz svg g')]
  const bars = [...pane.querySelectorAll('.bars div i')]
  const step = ms / li.length
  // Stage i lights at i*step; the tree grows during the parser's step; bars fill during the backends'.
  const frame = (t) => {
    li.forEach((el, i) => el.classList.toggle('on', t >= i * step))
    groups.forEach((g, d) => { g.style.opacity = t >= 2 * step + (d / Math.max(1, depth)) * step ? 1 : 0.06 })
    bars.forEach((b, i) => { b.style.width = t >= 5 * step + (i / bars.length) * step * 0.9 ? `${b.dataset.w}%` : '0' })
  }
  let t = 0
  let last = 0
  let raf = 0
  let playing = false
  const btn = pane.querySelector('[data-k="play"]')
  const sync = () => { btn.innerHTML = playing ? '&#10074;&#10074;' : '&#9654;'; btn.setAttribute('aria-label', playing ? 'Pause' : 'Play') }
  const tick = (now) => {
    t += now - last
    last = now
    frame(t)
    if (t >= ms) { playing = false; sync(); return }
    raf = requestAnimationFrame(tick)
  }
  const play = () => { if (t >= ms) t = 0; playing = true; last = performance.now(); sync(); raf = requestAnimationFrame(tick) }
  const pause = () => { playing = false; cancelAnimationFrame(raf); sync() }
  btn.addEventListener('click', () => (playing ? pause() : play()))
  pane.querySelector('[data-k="again"]').addEventListener('click', () => { pause(); t = 0; frame(0); play() })
  return {
    play,
    pause,
    end: () => { pause(); t = ms; frame(ms) },
    start: () => { pause(); t = 0; frame(0) },
  }
}

// --- tests --------------------------------------------------------------------------------------
function renderTests(pane, f, note) {
  const t = f.tests
  if (t.error) { pane.innerHTML = `<div class="tests"><p class="sum">The runner stopped: ${html(t.error)}</p><p class="note">${html(note)}</p></div>`; return }
  const mark = { pass: '&#10003;', fail: '&#10007;', skip: '&#8211;' }
  const rows = t.results.map((r) => {
    const failed = r.status === 'fail' ? (r.asserts ?? []).filter((a) => !a.ok).map((a) => `line ${a.line}${a.detail ? `: ${a.detail}` : ''}`) : []
    const why = r.reason || failed.join('; ')
    return `<div class="row ${r.status}"><span class="m">${mark[r.status]}</span><span class="kd">${r.kind}</span><span class="nm" title="line ${r.line}">${html(r.name)}</span><span class="kd">${(r.asserts ?? []).length} assert${(r.asserts ?? []).length === 1 ? '' : 's'}</span>${why ? `<span class="why">${html(why)}</span>` : ''}</div>`
  }).join('')
  pane.innerHTML = `<div class="tests"><p class="sum"><b>${t.pass}</b> pass &middot; <b>${t.fail}</b> fail &middot; <b>${t.skip}</b> skip &middot; ${t.results.length} block${t.results.length === 1 ? '' : 's'}</p>${rows || '<p class="sum">This spec has no test or invariant block.</p>'}<p class="note">${html(note)}</p></div>`
}

// --- code: what each backend emitted -----------------------------------------------------------
async function sha12(text) {
  if (!crypto.subtle) return ''
  const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return [...new Uint8Array(d)].slice(0, 6).map((b) => b.toString(16).padStart(2, '0')).join('')
}

function renderCode(pane, f, pick, stem) {
  const list = f.backends
  if (!list.length) { pane.innerHTML = '<p class="empty">No backend produced output for this file.</p>'; return }
  const cur = list.find((b) => b.name === pick && b.ok) || list.find((b) => b.ok) || list[0]
  pane.innerHTML = `<div class="code"><div class="chips">${list.map((b) => `<button type="button" data-b="${b.name}" aria-pressed="${b === cur}" class="${b.ok ? '' : 'x'}">${b.name}<small>${b.ok ? fmt(b.bytes) : 'failed'}</small></button>`).join('')}</div>
<pre>${cur.ok ? codeHtml(cur.code, cur.name) : html(cur.error || 'This backend produced no output.')}</pre>
<div class="meta"><span><code>${cur.name}</code> ${fmt(cur.bytes)} bytes</span><span>sha256 <code data-k="sha">&hellip;</code></span>${cur.ok ? `<button type="button" data-k="copy">copy</button><button type="button" data-k="save">${html(fileName(cur.name, cur.code, stem))}</button>` : ''}${cur.name === 'js' && cur.ok ? '<button type="button" data-k="run">import it here</button>' : ''}</div></div>`
  sha12(cur.code).then((h) => { const el = pane.querySelector('[data-k="sha"]'); if (el) el.textContent = h || 'n/a' })
  for (const b of pane.querySelectorAll('.chips button')) b.addEventListener('click', () => renderCode(pane, f, b.dataset.b, stem))
  pane.querySelector('[data-k="copy"]')?.addEventListener('click', (e) => copyText(cur.code, e.currentTarget))
  pane.querySelector('[data-k="save"]')?.addEventListener('click', () => download(cur.code, fileName(cur.name, cur.code, stem)))
  const run = pane.querySelector('[data-k="run"]')
  if (run) run.addEventListener('click', async () => {
    const out = await shell.importJs(cur.code, cfg)
    let pre = pane.querySelector('pre.out')
    if (!pre) { pre = document.createElement('pre'); pre.className = 'out'; pane.querySelector('.code').appendChild(pre) }
    pre.textContent = out
  })
}

// --- rtl: the emitted Verilog, read the way a hardware engineer reads it before synthesis ---------
const RTL_BACKENDS = ['verilog', 'verilog_hir']
const MARK = { error: '✕', warn: '⚠', info: '·' }
const plural = (n, one, many = one + 's') => `${fmt(n)} ${n === 1 ? one : many}`
const hex = (v) => (v === null ? '' : `0x${v.toString(16)}`)

function bitMap(s) {
  const K = site.CLS_COLOR
  const cycle = ['ident', 'num', 'str', 'kw', 'op', 'type']
  const drawn = s.fields.filter((x) => x.bits > 0)
  const colour = new Map(drawn.map((x, i) => [x.name, K[cycle[i % cycle.length]]]))
  const cells = drawn.slice().reverse().map((x) => {
    const tip = `${x.name}: ${x.type}, [${x.hi}:${x.lo}], ${plural(x.bits, 'bit')}${x.how === 'default' ? ', the 32-bit default' : ''}`
    const label = x.bits / s.bits >= 0.09 ? html(x.name) + (x.how === 'default' ? ' ⚠' : '') : ''
    return `<i class="${x.how === 'default' ? 'dflt' : ''}" style="flex:${x.bits} 1 0;background:${colour.get(x.name)}" title="${html(tip)}">${label}</i>`
  }).join('')
  const SHOW = 12
  const legend = drawn.slice().reverse().slice(0, SHOW).map((x) => `<span><b style="color:${colour.get(x.name)}">${html(x.name)}</b> [${x.hi}:${x.lo}]${x.how === 'default' ? ' <em class="w">⚠ default</em>' : ''}</span>`).join('')
  const more = drawn.length > SHOW ? `<span>+${drawn.length - SHOW} more</span>` : ''
  const strings = s.fields.filter((x) => x.bits === 0).map((x) => html(x.name))
  const said = s.stated === null ? '' : s.stated === s.bits ? ` &middot; <span class="ok">t27c says ${fmt(s.stated)} ✓</span>` : ` &middot; <span class="e">t27c says ${fmt(s.stated)}</span>`
  return `<div class="st"><div class="sn"><code>${html(s.name)}</code> ${plural(s.bits, 'bit')}${said}</div>
<div class="bits" role="img" aria-label="${html(s.name)}, ${s.bits} bits, most significant field first">${cells}</div>
<div class="scale"><span>${s.bits - 1}</span><span>0</span></div>
<div class="legend">${legend}${more}${strings.length ? `<span class="dim">no bits: ${strings.join(', ')}</span>` : ''}</div></div>`
}

function renderRtl(pane, f, analysis, pick, stem, openCode) {
  const list = f.backends.filter((b) => RTL_BACKENDS.includes(b.name))
  const cur = list.find((b) => b.name === pick && b.ok) || list.find((b) => b.ok)
  if (!cur) { pane.innerHTML = '<p class="empty">Neither Verilog backend produced output for this file.</p>'; return }
  let r
  try { r = readRtl(cur.code, analysis.ast) } catch (e) { pane.innerHTML = `<p class="empty">The Verilog reader stopped: ${html(e.message)}</p>`; return }
  const name = fileName(cur.name, cur.code, stem)
  const count = (lv) => r.findings.filter((x) => x.level === lv).length
  const errors = count('error')
  const warns = count('warn')
  const notes = count('info')
  const lowered = r.structs.filter((s) => s.lowered)
  const refused = r.structs.filter((s) => !s.lowered)
  const agree = lowered.filter((s) => s.stated !== null && s.stated === s.bits).length
  const stated = lowered.filter((s) => s.stated !== null).length

  const finds = r.findings.map((x) => `<li class="${x.level}"><span class="m">${MARK[x.level]}</span><span>${html(x.text)}</span><span class="ln">${x.line ? 'L' + x.line : ''}</span></li>`).join('')
  const unread = new Set(r.findings.filter((x) => /never read/.test(x.text)).flatMap((x) => x.text.split(': ')[1]?.replace(/\.$/, '').split(', ') ?? []))
  const ports = r.ports.map((p) => `<tr><td class="dim">${p.dir}</td><td class="n">${p.width}</td><td><code>${html(p.name)}</code>${unread.has(p.name.replace(/^\\/, '')) ? ' <span class="dim">unread</span>' : ''}</td></tr>`).join('')
  const params = r.params.map((p) => `<tr><td><code>${html(p.name)}</code></td><td class="n">${p.width}</td><td class="dim v" title="${html(p.text)}">${p.value !== null ? `${hex(p.value)} <span>(${p.value.toString()})</span>` : html(p.text.length > 28 ? p.text.slice(0, 27) + '…' : p.text)}</td></tr>`).join('')
  const fns = [...r.functions, ...r.tasks.map((t) => ({ ...t, task: true }))].map((x) => `<tr><td><code>${html(x.name)}</code></td><td class="dim">${x.inputs.map((i) => `${html(i.name.replace(/^\\/, ''))}<sub>${i.width}</sub>`).join(', ')}</td><td class="n">${x.task ? 'task' : '→ ' + x.width}</td><td class="dim">${x.returns ? html(x.returns) : ''}</td><td class="${x.loops.length ? 'w' : 'dim'}">${x.loops.map((n) => `${n}× loop`).join(', ')}</td></tr>`).join('')
  const tryCmds = [
    `iverilog -g2005 -o /dev/null ${name}`,
    `verilator --lint-only -Wall ${name}`,
    r.module ? `yosys -p "read_verilog ${name}; synth -top ${r.module}; stat"` : null,
  ].filter(Boolean)

  pane.innerHTML = `<div class="rtl">
<div class="top"><div class="chips">${list.map((b) => `<button type="button" data-b="${b.name}" aria-pressed="${b === cur}" class="${b.ok ? '' : 'x'}">${b.name}<small>${b.ok ? fmt(b.bytes) : 'failed'}</small></button>`).join('')}</div>
<span class="mod">module <code>${html(r.module ?? '?')}</code> &middot; ${plural(r.lines, 'line')} &middot; ${fmt(r.bytes)} bytes</span>
<span class="act"><button type="button" data-k="copy">copy</button><button type="button" data-k="save">${html(name)}</button><button type="button" data-k="src">source</button></span></div>
<div class="sum"><b class="${errors ? 'e' : 'ok'}">${plural(errors, 'error')}</b><b class="${warns ? 'w' : 'ok'}">${plural(warns, 'warning')}</b><span>${plural(notes, 'note')}</span>${r.checked.of ? `<span>${r.checked.slices}/${r.checked.of} part-selects on a field</span>` : ''}${stated ? `<span>${agree}/${stated} struct widths as t27c states them</span>` : ''}</div>
<h4>What a Verilog-2005 reader meets <span>a scan in your browser, not a tool run</span></h4>
<ul class="finds">${finds || '<li class="info"><span class="m">·</span><span>Nothing found.</span><span></span></li>'}</ul>
${lowered.length ? `<h4>Packed structs <span>msb left &middot; lsb right</span></h4>${lowered.slice(0, 8).map(bitMap).join('')}${lowered.length > 8 ? `<p class="dim">+${lowered.length - 8} more packed structs</p>` : ''}` : ''}
${refused.length ? `<p class="dim">Not packed by t27c: ${refused.map((s) => `<code>${html(s.name)}</code>`).join(', ')} (a float, an unsized slice, or a struct that is not packed).</p>` : ''}
<div class="cols">
<div><h4>Ports <span>${r.ports.length}</span></h4><table>${ports || '<tr><td class="dim">none</td></tr>'}</table></div>
${r.params.length ? `<div><h4>Parameters <span>${r.params.length}</span></h4><table>${params}</table></div>` : ''}
</div>
${fns ? `<h4>Functions <span>inputs<sub>bits</sub> &middot; result bits &middot; t27 type</span></h4><table class="fn">${fns}</table>` : ''}
<h4>Try it on your machine <button type="button" data-k="cmds" class="cp">copy</button></h4>
<pre class="try">${tryCmds.map((c) => `<span class="p">$ </span>${html(c)}`).join('\n')}</pre>
<p class="note">Read from the emitted text in your browser: a scan, not a tool run. The struct bit maps restate t27c's packing rule and are checked against what gen-verilog wrote.</p>
</div>`
  for (const b of pane.querySelectorAll('.chips button')) b.addEventListener('click', () => renderRtl(pane, f, analysis, b.dataset.b, stem, openCode))
  pane.querySelector('[data-k="copy"]').addEventListener('click', (e) => copyText(cur.code, e.currentTarget))
  pane.querySelector('[data-k="save"]').addEventListener('click', () => download(cur.code, name))
  pane.querySelector('[data-k="src"]').addEventListener('click', () => openCode(cur.name))
  pane.querySelector('[data-k="cmds"]').addEventListener('click', (e) => copyText(tryCmds.join('\n'), e.currentTarget))
}

// --- term: a terminal over the same compiler (./shell.js), and the recording of t27c ------------
async function replayCast(el, cast, specName) {
  try {
    const { mount } = await import(at('term/player.js').href)
    mount(el, { src: new URL(`term/${cast}/session.cast`, root).href, title: `t27c on ${specName}`, share: new URL(`term/${cast}/`, root).href })
  } catch (e) {
    el.innerHTML = `<p class="empty">The recording did not load: ${html(e.message)}</p>`
  }
}

// --- the page -----------------------------------------------------------------------------------
async function main() {
  const v = build ? `?v=${build}` : ''
  ;[site, { readRtl }, shell] = await Promise.all([
    import(new URL('site.js' + v, import.meta.url).href).catch((e) => { throw new Error(`site.js did not load: ${e.message}`) }),
    import(new URL('rtl.js' + v, import.meta.url).href).catch((e) => { throw new Error(`rtl.js did not load: ${e.message}`) }),
    import(new URL('shell.js' + v, import.meta.url).href).catch((e) => { throw new Error(`shell.js did not load: ${e.message}`) }),
  ])
  for (const [k, c] of Object.entries(site.CLS_COLOR)) document.documentElement.style.setProperty(`--h-${k}`, c)
  for (const [k, c] of Object.entries(site.C)) if (typeof c === 'string' && !/[;{}]/.test(c)) document.documentElement.style.setProperty(`--c-${k}`, c)
  const analyze = await loadCompiler()
  status('compiling player.t27&hellip;')
  const orchRes = await fetch(new URL('player.t27' + (build ? `?v=${build}` : ''), import.meta.url))
  if (!orchRes.ok) throw new Error(`player.t27 did not load (HTTP ${orchRes.status})`)
  cfg = playerConfig(analyze(await orchRes.text(), 'player.t27'))
  document.documentElement.style.setProperty('--ed-touch-font', `${cfg.EDITOR_TOUCH_FONT_PX}px`)

  const specPath = query.get('spec') || cfg.PLAY_SPECS[0]
  if (!SPEC_PATH_RE.test(specPath) || specPath.includes('..')) throw new Error(`not a spec path: ${specPath}`)
  const playIndex = cfg.PLAY_SPECS.indexOf(specPath)
  const castParam = query.get('cast')
  const cast = castParam && CAST_ID_RE.test(castParam) ? castParam : playIndex >= 0 ? cfg.PLAY_CASTS[playIndex] : null
  const specName = specPath.split('/').pop()
  const stem = specName.replace(/\.t27$/, '')
  $('#file').textContent = specPath.replace(/^specs\//, '')
  $('#open').href = `${cfg.ORIGIN}${cfg.SPEC_PAGE}${encodeURIComponent(specPath)}`
  document.title = `${specName} \u00b7 t27`

  status(`loading ${html(specName)}&hellip;`)
  const res = await fetch(new URL(`t27/files/${specPath}`, root))
  if (!res.ok) throw new Error(`${specPath} is not published (HTTP ${res.status})`)
  let source = await res.text()

  // Tabs, from the spec.
  const tabs = cfg.TABS.map((id, i) => ({ id, label: cfg.TAB_LABELS[i] }))
  const nav = $('#tabs')
  nav.innerHTML = tabs.map((t) => `<button role="tab" type="button" data-tab="${t.id}"${t.id === 'spec' ? ' class="tab-spec"' : ''}>${html(t.label)}</button>`).join('')
  const wideQuery = matchMedia(`(min-width: ${cfg.WIDE_MIN_PX}px) and (min-aspect-ratio: 4/3)`)
  let current = null
  const select = (id) => {
    if (wideQuery.matches && id === 'spec') id = cfg.FIRST_TAB
    current = id
    for (const b of nav.querySelectorAll('button')) b.setAttribute('aria-selected', String(b.dataset.tab === id))
    for (const p of document.querySelectorAll('.pane')) p.classList.toggle('on', p.id === `pane-${id}`)
    if (id === 'term') openTerm()
    if (id !== 'compile' && player) player.end()
  }
  const layout = () => {
    $('#main').classList.toggle('wide', wideQuery.matches)
    document.body.classList.toggle('wide', wideQuery.matches)
    if (current) select(current)
  }
  wideQuery.addEventListener('change', layout)
  nav.addEventListener('click', (e) => { const b = e.target.closest('button[data-tab]'); if (b) select(b.dataset.tab) })

  // One compile, every tab redrawn from it.
  let player = null
  let codePick = null
  let rtlPick = null
  const openCode = (backend) => { codePick = backend; renderCode($('#pane-code'), last, codePick, stem); select('code') }
  let last = null
  let painted = { lines: [], html: [] }
  const draw = (animate) => {
    const t0 = performance.now()
    const analysis = analyze(source, specName)
    const f = factsOf(source, analysis)
    last = f
    const ms = performance.now() - t0
    const rows = site.highlightSource(source, analysis.tokens ?? [])
    painted = { lines: source.split('\n'), html: highlight(rows, analysis) }
    $('#hl').innerHTML = painted.html.join('')
    const depth = renderCompile($('#pane-compile'), f, analysis, classCounts(rows))
    if (player) player.pause()
    player = piece($('#pane-compile'), depth, cfg.COMPILE_ANIMATION_MS)
    if (animate) { player.start(); player.play() } else player.end()
    renderTests($('#pane-tests'), f, cfg.TESTS_NOTE)
    renderCode($('#pane-code'), f, codePick, stem)
    $('#pane-code').onclick = (e) => { const b = e.target.closest('.chips button'); if (b) codePick = b.dataset.b }
    renderRtl($('#pane-rtl'), f, analysis, rtlPick, stem, openCode)
    $('#pane-rtl').onclick = (e) => { const b = e.target.closest('.chips button'); if (b) rtlPick = b.dataset.b }
    const ok = f.typeOk && f.hirOk && !f.astError
    const t = f.tests
    status(`<b>${html(specName)}</b> &middot; <span class="${ok ? 'ok' : 'bad'}">${ok ? 'compiles' : 'does not compile'}</span> in ${ms.toFixed(0)} ms &middot; ${fmt(f.tokens)} tokens &middot; ${fmt(f.nodes)} nodes &middot; ${f.backends.filter((b) => b.ok).length}/${f.backends.length} backends &middot; tests ${t.pass}/${t.results.length} pass${t.fail ? ` <span class="bad">${t.fail} fail</span>` : ''}${t.skip ? ` &middot; ${t.skip} skip` : ''}`)
  }

  const src = $('#src')
  src.value = source
  let timer = 0
  src.addEventListener('input', () => {
    $('#hl').innerHTML = repaint(src.value.split('\n'), painted).join('')
    // The textarea never scrolls itself; the pane does. Before the coloured layer has grown, a new
    // longest line or a new last line can scroll it, and its caret drifts off the drawn text.
    src.scrollLeft = 0
    src.scrollTop = 0
    clearTimeout(timer)
    timer = setTimeout(() => { source = src.value; draw(false) }, cfg.RECOMPILE_DEBOUNCE_MS)
  })
  src.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return
    e.preventDefault()
    const { selectionStart: a, selectionEnd: b } = src
    src.setRangeText('    ', a, b, 'end')
    src.dispatchEvent(new Event('input'))
  })

  // The terminal, mounted the first time its tab opens. On a backend's share page with autoplay,
  // it types SHELL_DEMO for that backend, at SHELL_TYPE_MS a character, and runs it.
  let term = null
  const openTerm = () => {
    if (term) return
    term = shell.mountShell($('#pane-term'), {
      cfg, specName, stem, analyze, download, codeHtml,
      source: () => src.value,
      specHtml: (analysis) => site.highlightSource(src.value, analysis.tokens ?? []).map(spansHtml).join('\n'),
      replay: cast ? (el) => replayCast(el, cast, specName) : null,
      backend: query.get('backend'),
    })
    if (autoplay && !reduced && query.get('tab') === 'term') term.type(cfg.SHELL_DEMO.replaceAll('{backend}', cfg.BACKENDS.includes(query.get('backend')) ? query.get('backend') : cfg.BACKENDS[0]), cfg.SHELL_TYPE_MS)
  }

  const autoplay = cfg.AUTOPLAY_PARAMS.some((k) => ['1', 'true'].includes(query.get(k)))
  layout()
  const want = query.get('tab')
  select(tabs.some((t) => t.id === want) ? want : cfg.FIRST_TAB)
  draw(autoplay && !reduced)
}

main().catch((e) => {
  status(`the player stopped: ${html(e.message)}`, 'bad')
  console.error(e)
})
